#define CHECK(x) do{if(!(x)){std::fprintf(stderr,"FAIL %d %s\n",__LINE__,#x);std::exit(1);}}while(false)
struct Event{unsigned frame,key;bool on;};
struct Trace{std::unique_ptr<blocks_detail::NoteRack>r=std::make_unique<blocks_detail::NoteRack>();unsigned frame=0,panics=0;std::vector<Event>events;Trace(){events.reserve(1024);r->bind({this,[](void*p,unsigned,unsigned key,float){auto&t=*static_cast<Trace*>(p);t.events.push_back({t.frame,key,true});},[](void*p,unsigned,unsigned key){auto&t=*static_cast<Trace*>(p);t.events.push_back({t.frame,key,false});},nullptr,[](void*p){++static_cast<Trace*>(p)->panics;}});}void until(unsigned n){while(frame<n){r->tick();++frame;}}std::vector<unsigned>ons(){std::vector<unsigned>x;for(auto&e:events)if(e.on)x.push_back(e.frame);return x;}};
static bs_notes_config config(unsigned type){auto c=blocks_detail::NoteRack::defaults();c.count=1;auto&b=c.blocks[0];b.id=7;b.type=type;b.enabled=1;b.drop_time=.12f;b.perf=blocks_detail::defaultPerformance();b.perf.mode=type==BS_NOTE_ARP?BS_ARP:BS_STRUM;b.perf.division=4;b.perf.gate=.5f;b.perf.strum_ms=100;b.perf.randomness=0;return c;}
struct Synth{bs_synth*s=bs_create();Synth(){CHECK(s&&bs_prepare(s,48000));for(auto p:{std::pair<unsigned,float>{BS_GAIN,.1f},{BS_OSC1_LEVEL,.5f},{BS_OSC2_LEVEL,0},{BS_OSC1_WAVE,BS_SINE},{BS_FILTER_MIX,0},{BS_FULLNESS_ENABLED,0},{BS_DRIFT_CENTS,0},{BS_SETTLING_CENTS,0},{BS_ATTACK,.001f},{BS_SUSTAIN_LEVEL,1},{BS_RELEASE,.001f}})CHECK(bs_set_parameter(s,p.first,p.second));bs_reset(s);}~Synth(){bs_destroy(s);}};
static std::vector<float> render(bs_synth*s,unsigned n,unsigned block=127){std::vector<float>x(n*2);for(unsigned i=0;i<n;i+=block)CHECK(!bs_render(s,x.data()+i,x.data()+n+i,std::min(block,n-i),nullptr,0));for(float v:x)CHECK(std::isfinite(v));return x;}
static bs_modulation_config_v4 route(unsigned p,float depth){bs_modulation_config_v4 c{};bs_default_modulation_v4(&c);auto&l=c.sources[0];l.enabled=1;l.waveform=BS_LFO_CUSTOM;l.point_count=2;l.points[0]={0,1,0};l.points[1]={1,1,0};l.route_count=1;l.routes[0]={6,7,p,depth};return c;}
int main(){
 {Trace t;auto base=config(BS_NOTE_ARP);CHECK(t.r->configure(base,48000));t.r->on(0,60,.7f);t.until(1000);const auto panic=t.panics;auto effective=base;effective.blocks[0].perf.bpm=240;effective.blocks[0].perf.division=8;effective.blocks[0].perf.gate=.25f;CHECK(t.r->configureEffective(effective));CHECK(t.r->pendingMask()==1);CHECK(!std::memcmp(&t.r->config(),&base,sizeof base));t.until(102001);auto ons=t.ons();CHECK(ons==std::vector<unsigned>({0,24000,48000,72000,96000,102000}));CHECK(t.r->effectiveBlock(7).perf.bpm==240&&t.r->pendingMask()==0);CHECK(std::any_of(t.events.begin(),t.events.end(),[](const Event&e){return !e.on&&e.frame==97500;}));t.r->restoreEffective();CHECK(t.r->pendingMask()==1);t.until(168001);ons=t.ons();CHECK(std::find(ons.begin(),ons.end(),144000)!=ons.end());CHECK(std::find(ons.begin(),ons.end(),168000)!=ons.end());CHECK(t.r->effectiveBlock(7).perf.bpm==120&&t.panics==panic);t.r->off(0,60);const auto attacks=t.ons().size();t.until(240001);CHECK(t.ons().size()==attacks);}
 std::puts("PASS Arp effective tempo/division/gate adopt at bar seam and removal restores without panic or saved mutation");
 {Trace t;auto base=config(BS_NOTE_ARP);CHECK(t.r->configure(base,48000));auto effective=base;effective.blocks[0].perf.curl=.8f;CHECK(t.r->configureEffective(effective));t.r->on(0,60,.7f);t.until(96001);auto ons=t.ons();CHECK(ons.size()==5&&ons.front()==0&&ons.back()==96000);CHECK(ons[1]>24000&&ons[3]<96000);for(unsigned i=1;i<ons.size();i++)CHECK(ons[i]>ons[i-1]);}
 std::puts("PASS modulated Curl preserves exact four-beat endpoint and monotone event order");
 {Trace t;auto base=config(BS_NOTE_STRUM);CHECK(t.r->configure(base,48000));for(unsigned k:{60u,64u,67u})t.r->on(0,k,.7f);t.until(500);auto effective=base;effective.blocks[0].perf.strum_ms=0;CHECK(t.r->configureEffective(effective));t.until(6000);CHECK(t.ons()==std::vector<unsigned>({960,3360,5760}));for(unsigned k:{60u,64u,67u})t.r->off(0,k);for(unsigned k:{60u,64u,67u})t.r->on(0,k,.7f);CHECK(t.ons()==std::vector<unsigned>({960,3360,5760,6000,6000,6000}));for(unsigned k:{60u,64u,67u})t.r->off(0,k);CHECK(t.r->configureEffective(base));for(unsigned k:{60u,64u,67u})t.r->on(0,k,.7f);t.until(6500);CHECK(t.r->configureEffective(effective));for(unsigned k:{60u,64u,67u})t.r->off(0,k);t.until(13000);CHECK(t.ons().size()==6);}
 std::puts("PASS Strum keeps published/collecting chord timing, applies next collection and cancels released queues");
 {Trace a,b;auto base=config(BS_NOTE_STRUM);CHECK(a.r->configure(base,48000)&&b.r->configure(base,48000));auto effective=base;effective.blocks[0].perf.randomness=1;CHECK(b.r->configureEffective(effective));for(unsigned k:{60u,64u,67u,72u}){a.r->on(0,k,.7f);b.r->on(0,k,.7f);}a.until(6000);b.until(6000);auto straight=a.ons(),human=b.ons();CHECK(straight.size()==4&&human.size()==4&&straight.front()==human.front()&&straight.back()==human.back()&&straight!=human);for(unsigned i=1;i<human.size();++i)CHECK(human[i]>human[i-1]);}
 std::puts("PASS Strum Humanize changes interior spacing while preserving bounded endpoints and event order");
 for(unsigned parameter=0;parameter<3;++parameter){Synth a,b;auto n=config(BS_NOTE_DROP);if(parameter)n.blocks[0].drop_amount=1200;CHECK(bs_set_notes(a.s,&n)&&bs_set_notes(b.s,&n));bs_note_on(a.s,0,48,.8f);bs_note_on(b.s,0,48,.8f);CHECK(render(a.s,4000)==render(b.s,4000));auto m=route(parameter,parameter?.25f:.5f);CHECK(bs_set_modulation_v4(b.s,&m));CHECK(render(a.s,5000)==render(b.s,5000));CHECK(bs_get_modulated_target_value(b.s,6,7,parameter)>(parameter==0?1199:parameter==1?.12:0));bs_note_on(a.s,0,60,.8f);bs_note_on(b.s,0,60,.8f);CHECK(render(a.s,8000)!=render(b.s,8000));bs_notes_config got{};CHECK(bs_get_notes(b.s,&got)&&!std::memcmp(&got,&n,sizeof n));m.sources[0].route_count=0;CHECK(bs_set_modulation_v4(b.s,&m));render(b.s,500);CHECK(std::abs(bs_get_modulated_target_value(b.s,6,7,parameter)-(parameter==1?.12:0))<1e-6);bs_panic(b.s);render(b.s,5000);CHECK(bs_active_voices(b.s)==0);}
 std::puts("PASS actual Drop amount/time/bend modulation changes new-attack PCM only, restores recipe and preserves requested state");
 {Synth a,b;auto n=config(BS_NOTE_ARP);CHECK(bs_set_notes(a.s,&n)&&bs_set_notes(b.s,&n));auto m=route(3,.6f);CHECK(bs_set_modulation_v4(a.s,&m)&&bs_set_modulation_v4(b.s,&m));render(a.s,1024,1);render(b.s,1024,256);bs_note_on(a.s,0,60,.8f);bs_note_on(b.s,0,60,.8f);CHECK(render(a.s,60000,1)==render(b.s,60000,256));CHECK(bs_get_modulated_target_value(a.s,6,7,3)==240);m.sources[0].route_count=0;CHECK(bs_set_modulation_v4(a.s,&m));render(a.s,60000);CHECK(bs_get_modulated_target_value(a.s,6,7,3)==120);bs_notes_config got{};CHECK(bs_get_notes(a.s,&got)&&got.blocks[0].perf.bpm==120);bs_note_off(a.s,0,60);render(a.s,10000);CHECK(bs_active_voices(a.s)==0);}
 std::puts("PASS native route scheduling is block-exact, restores requested tempo and releases actual voices");
}
